import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import type { CreateHost } from '../host.ts';

const factory: CreateHost = createHost;

test('full lifecycle with charge ok, ship', async () => {
  const h = await factory();
  assert.deepEqual(await h.create('a'), { ok: true });
  assert.equal((await h.create('a')).ok, false);
  assert.equal((await h.place('a')).ok, false);
  for (let i = 0; i < 3; i++) assert.equal((await h.addItem('a')).ok, true);
  assert.equal((await h.addItem('a')).ok, false);
  assert.equal((await h.removeItem('a')).ok, true);
  assert.equal((await h.place('a')).ok, true);
  assert.equal((await h.ship('a')).ok, false);
  const effs = await h.pendingEffects();
  assert.equal(effs.length, 1);
  assert.deepEqual({ ...effs[0], id: '' }, { id: '', from: 'a', kind: 'payment.charge', data: { amount: 2 } });
  await h.completeEffect(effs[0].id, 'ok');
  assert.deepEqual(await h.pendingEffects(), []);
  assert.deepEqual(await h.order('a'), { status: 'paid', items: 2, charges: 1, refunds: 0 });
  assert.equal((await h.ship('a')).ok, true);
  assert.equal((await h.cancel('a')).ok, false);
  assert.deepEqual(await h.order('a'), { status: 'shipped', items: 2, charges: 1, refunds: 0 });
});

test('failed charge, refund on paid cancel, unknown order', async () => {
  const h = await factory();
  assert.equal(await h.order('x'), null);
  assert.equal((await h.addItem('x')).ok, false);
  await h.create('a'); await h.addItem('a'); await h.place('a');
  await h.create('b'); await h.addItem('b'); await h.place('b');
  const effs = await h.pendingEffects();
  await h.completeEffect(effs.find((e) => e.from === 'a')!.id, 'failed');
  await h.completeEffect(effs.find((e) => e.from === 'b')!.id, 'ok');
  assert.equal((await h.order('a'))!.status, 'declined');
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.cancel('b')).ok, true);
  assert.deepEqual(await h.order('b'), { status: 'cancelled', items: 1, charges: 1, refunds: 1 });
  assert.deepEqual(await h.pendingEffects(), []);
  await h.create('c');
  assert.equal((await h.removeItem('c')).ok, false);
  assert.equal((await h.cancel('c')).ok, true);
  assert.equal((await h.addItem('c')).ok, false);
});

test('cancel while the payment is in progress', async () => {
  const h = await factory();
  for (const id of ['a', 'b']) { await h.create(id); await h.addItem(id); await h.place(id); }
  assert.equal((await h.cancel('a')).ok, true);
  assert.equal((await h.cancel('b')).ok, true);
  assert.deepEqual(await h.order('a'), { status: 'cancelling', items: 1, charges: 1, refunds: 0 });
  for (const c of ['addItem', 'removeItem', 'place', 'ship', 'cancel', 'retryPayment'] as const) {
    assert.equal((await h[c]('a')).ok, false, c);
  }
  const effs = await h.pendingEffects();
  assert.equal(effs.length, 2);
  await h.completeEffect(effs.find((e) => e.from === 'a')!.id, 'ok');
  await h.completeEffect(effs.find((e) => e.from === 'b')!.id, 'failed');
  assert.deepEqual(await h.order('a'), { status: 'cancelled', items: 1, charges: 1, refunds: 1 });
  assert.deepEqual(await h.order('b'), { status: 'cancelled', items: 1, charges: 1, refunds: 0 });
  assert.deepEqual(await h.pendingEffects(), []);

